          <p class="font-semibold text-slate-900">Choose Your First Workflow</p>
          <p class="text-slate-600 text-sm">Pick the simplest, most repeatable task to automate first.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'What a Workflow Does',
      lesson_number = 1,
      sort_order = 1,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: What a Workflow Does';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: What a Workflow Does

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 10 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 10 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'what-workflow-does' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson what-workflow-does not found in module 10';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is a workflow?', 
    '["A type of contact","A set of instructions LeadProspectrr follows automatically after a specific event","A payment method","A report type"]'::jsonb,
    'A set of instructions LeadProspectrr follows automatically after a specific event',
    'A workflow is a set of automatic instructions that LeadProspectrr follows when a specific trigger event occurs. It repeats the process consistently each time.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What makes a good first workflow?', 
    '["A 90-day sales process with twelve emails and many branches","One clear starting event, one contact type, 3-4 actions, one owner, easy to test","Complex processes with many exceptions","No clear starting point"]'::jsonb,
    'One clear starting event, one contact type, 3-4 actions, one owner, easy to test',
    'A good first workflow is simple: one clear trigger, one contact type, 3-4 actions, one person responsible, and results that are easy to test.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you avoid as a first workflow?', 
    '["Simple form confirmations","Long processes with many branches, messages, offers, and exceptions","Tagging contacts","Sending emails"]'::jsonb,
    'Long processes with many branches, messages, offers, and exceptions',
    'Avoid complex first workflows with many branches and exceptions. Start with a simple, linear process that fits on one screen.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
